package main

// Two languages: Persian (right to left) and English. Every text the user
// sees is written in Persian in the code and passed through T(), which
// returns the English text when the window is in English. Technical words
// (Windows Firewall, Rule, Group Policy ...) are English in both.

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// lang is "fa" or "en"; set once at start, before the window is made.
var lang = "fa"

// T translates a Persian text (a fmt format when args are given).
func T(fa string, args ...any) string {
	msg := fa
	if lang == "en" {
		if e, ok := english[fa]; ok {
			msg = e
		}
	}
	if len(args) > 0 {
		return fmt.Sprintf(msg, args...)
	}
	return msg
}

// listSep: the comma between items of a list.
func listSep() string {
	if lang == "en" {
		return ", "
	}
	return "، "
}

// appTitle: the program name and version, shown in the title bar.
func appTitle() string {
	if lang == "en" {
		return AppName + "  " + Version
	}
	return "فیلتر IP کشورها  " + ltr(Version)
}

// ---------------------------------------------------------------- the chosen language

func (c *Core) settingsPath() string { return filepath.Join(c.Dir, "settings.txt") }

// LoadLang returns the saved language ("" when none was chosen yet).
func (c *Core) LoadLang() string {
	b, _ := os.ReadFile(c.settingsPath())
	for _, l := range strings.Split(string(b), "\n") {
		k, v, _ := strings.Cut(strings.TrimSpace(l), "=")
		if k == "lang" && (v == "fa" || v == "en") {
			return v
		}
	}
	return ""
}

func (c *Core) SaveLang(l string) error {
	return writeFileAtomic(c.settingsPath(), []byte("lang="+l+"\r\n"))
}

